package androidx.core.content;

public final class ContextCompat {
  private ContextCompat() {}
  public static int checkSelfPermission(android.content.Context context, String permission) { return com.getcapacitor.Plugin.permission == com.getcapacitor.PermissionState.GRANTED ? 0 : -1; }
}
